#include <iostream>

// read-only input: a pointer to const plus a length
double average(const int* values, int count)
{
    if (count <= 0) return 0;
    int sum = 0;
    for (int i = 0; i < count; i++) sum += values[i];
    return static_cast<double>(sum) / count;
}

int main()
{
    int readings[4] = {40, 75, 90, 20};
    int* p = readings;                  // the array becomes a pointer to readings[0]
    std::cout << *(p + 2) << " " << p[2] << "\n";

    std::cout << "average " << average(readings, 4) << "\n";
    std::cout << "middle two " << average(readings + 1, 2) << "\n";

    // a range: begin and one-past-the-end
    for (const int* q = readings; q != readings + 4; ++q)
        std::cout << *q << " ";
    std::cout << "\n";
    return 0;
}

