int countAbove(const int* begin, const int* end, int limit)
{
    int n = 0;
    for (const int* p = begin; p != end; ++p)   // stop at one-past-the-end
        if (*p > limit) n++;
    return n;
}

void reverseInPlace(int* values, int count)
{
    if (count < 2) return;
    int* left = values;
    int* right = values + count - 1;   // the last item, not one past it
    while (left < right) {
        int t = *left;
        *left = *right;
        *right = t;
        ++left;
        --right;
    }
}
